# Let's verify the Moore bound reasoning
# For a graph with minimum degree delta and girth 2k (even),
# the number of vertices n >= 1 + delta + delta*(delta-1) + ... + delta*(delta-1)^(k-1)

def moore_bound_even(delta, k):
    """Lower bound on vertices for min degree delta and girth 2k"""
    total = 1
    term = 1
    for i in range(k):
        if i == 0:
            term = 1
        else:
            term = term * (delta - 1) if i == 1 else term * (delta - 1)
        # Actually let me just compute directly
    # n >= 1 + delta + delta*(delta-1) + ... + delta*(delta-1)^(k-1)
    total = 1
    for i in range(k):
        if i == 0:
            total += 0  # the 1 is already counted
        elif i == 1:
            total += delta
        else:
            total += delta * (delta - 1) ** (i - 1)
    return total

for delta in range(3, 8):
    bound = moore_bound_even(delta, 3)  # girth 6 => k=3
    print(f"delta={delta}: lower bound = {bound}, need 28 vertices -> {'POSSIBLE' if bound <= 28 else 'IMPOSSIBLE'}")

import itertools

F = [0, 1, 2]

def normalize(v):
    for s in [1, 2]:
        nv = tuple((s * x) % 3 for x in v)
        if nv < v:
            return nv
    return v

# Points (1-dim subspaces)
points_set = set()
points_list = []
for v in itertools.product(F, repeat=3):
    if v == (0, 0, 0):
        continue
    nv = normalize(v)
    if nv not in points_set:
        points_set.add(nv)
        points_list.append(nv)

print(f"Points: {points_list}")

# Lines (2-dim subspaces) - each line is the set of points orthogonal to a non-zero vector
lines_list = []
for d in points_list:
    line = []
    for p in points_list:
        dot = (p[0]*d[0] + p[1]*d[1] + p[2]*d[2]) % 3
        if dot == 0:
            line.append(p)
    lines_list.append(line)

print(f"Lines:")
for i, line in enumerate(lines_list):
    print(f"  Line {i}: {line}")

# Build incidence graph
edges = []
for i, p in enumerate(points_list):
    for j, line in enumerate(lines_list):
        if p in line:
            edges.append((i, 13 + j))

print(f"\nNumber of edges: {len(edges)}")
deg = [0] * 26
for u, v in edges:
    deg[u] += 1
    deg[v] += 1
print(f"Degrees: {sorted(deg)}")
print(f"Min: {min(deg)}, Max: {max(deg)}")
